open Chakravala_autogen
open Z

let test_chakravala =
  let test num ~expected_a ~expected_b =
    ( Printf.sprintf "chakravala(%d)" num,
      `Quick,
      fun () ->
        let n = Z.of_int num in
        let expected = (expected_a, expected_b) in
        let Pair (a, b) = chakravala n in
        Alcotest.(check (pair string string)) "same a & b" expected (Z.to_string a, Z.to_string b);
        Alcotest.(check bool) "a^2 - N b^2 = 1" true (a * a - n * b * b == Z.of_int 1)
     )
  in
  [
    test 9  ~expected_a:"1" ~expected_b:"0";
    test 61 ~expected_a:"1766319049" ~expected_b:"226153980";
    test 109 ~expected_a:"158070671986249" ~expected_b:"15140424455100";
    test 277 ~expected_a:"159150073798980475849" ~expected_b:"9562401173878027020";
    test 1000009 ~expected_a:"" ~expected_b:"";
  ]

let suite = [ ("chakravala", test_chakravala) ]

let () = Alcotest.run __FILE__ suite